1	package net.officefloor.hq.app;
2	
3	import java.math.BigDecimal;
4	import java.util.List;
5	import org.springframework.jdbc.core.JdbcTemplate;
6	import org.springframework.jdbc.support.GeneratedKeyHolder;
7	import org.springframework.jdbc.support.KeyHolder;
8	import org.springframework.stereotype.Repository;
9	
10	/** Data access for {@link Invoice} rows (JdbcTemplate over the schema in V4__invoices.sql). */
11	@Repository
12	public class InvoiceRepository {
13	
14	    private final JdbcTemplate jdbc;
15	
16	    public InvoiceRepository(JdbcTemplate jdbc) {
17	        this.jdbc = jdbc;
18	    }
19	
20	    private static final org.springframework.jdbc.core.RowMapper<Invoice> MAPPER =
21	            (rs, i) -> new Invoice(rs.getLong("id"), rs.getLong("project_id"),
22	                    rs.getBigDecimal("amount"), rs.getString("status"),
23	                    rs.getString("issued_date"), rs.getString("due_date"),
24	                    rs.getBigDecimal("due"), rs.getBigDecimal("discount_pct"),
25	                    rs.getBigDecimal("tax_pct"));
26	
27	    // An invoice's amount is the sum of its line items (qty * unit_price); a line-item-less invoice
28	    // totals zero. Derived here so the amount always reflects the current line items.
29	    private static final String AMOUNT_SUM =
30	            "COALESCE((SELECT SUM(li.qty * li.unit_price) FROM line_items li"
31	                    + " WHERE li.invoice_id = i.id), 0)";
32	
33	    // What has been paid against the invoice: the sum of its payments (zero when none). The amount
34	    // still due is the invoice amount minus this.
35	    private static final String PAID_SUM =
36	            "COALESCE((SELECT SUM(pm.amount) FROM payments pm"
37	                    + " WHERE pm.invoice_id = i.id), 0)";
38	
39	    // An invoice can carry a percentage discount (discount_pct, V29) taken off its amount; the
40	    // discounted amount is what the client is actually billed. Kept separate from AMOUNT_SUM so the
41	    // subtotal still reads as the raw line-item total.
42	    private static final String DISCOUNTED_AMOUNT =
43	            "(" + AMOUNT_SUM + " * (100 - i.discount_pct) / 100)";
44	
45	    // Sales tax (tax_pct, V30) is added on top after the discount, so the taxed amount is the
46	    // discounted amount times (1 + tax_pct/100). This is what the client actually pays.
47	    private static final String TAXED_AMOUNT =
48	            "(" + DISCOUNTED_AMOUNT + " * (100 + i.tax_pct) / 100)";
49	
50	    // What is still owed on the invoice: its taxed (post-discount) amount minus what has been paid,
51	    // so the discount and the tax both flow through everywhere "owed" is shown.
52	    private static final String DUE = "(" + TAXED_AMOUNT + " - " + PAID_SUM + ")";
53	
54	    // An invoice's status is worked out from its recorded payments, not flipped by hand: it stays
55	    // DRAFT until issued, reads SENT once issued but unpaid, PARTIAL once some (but not all) of the
56	    // amount is paid, and PAID once the payments cover the amount. Derived here so the status always
57	    // reflects the payments on file.
58	    private static final String DERIVED_STATUS =
59	            "CASE WHEN i.status = 'VOID' THEN 'VOID'"
60	                    + " WHEN i.status = 'DRAFT' THEN 'DRAFT'"
61	                    + " WHEN " + AMOUNT_SUM + " > 0 AND " + PAID_SUM + " >= " + AMOUNT_SUM
62	                    + " THEN 'PAID'"
63	                    + " WHEN " + PAID_SUM + " > 0 THEN 'PARTIAL'"
64	                    + " ELSE 'SENT' END";
65	
66	    public List<Invoice> findByProject(long projectId) {
67	        return jdbc.query(
68	                "SELECT i.id, i.project_id, " + AMOUNT_SUM + " AS amount, " + DUE + " AS due,"
69	                        + " " + DERIVED_STATUS + " AS status, i.issued_date, i.due_date, i.discount_pct, i.tax_pct"
70	                        + " FROM invoices i WHERE i.project_id = ? ORDER BY i.id",
71	                MAPPER, projectId);
72	    }
73	
74	    /** A project's invoices ordered by due date, earliest first (nulls last, id as tiebreak). */
75	    public List<Invoice> findByProjectOrderByDueDate(long projectId) {
76	        return jdbc.query(
77	                "SELECT i.id, i.project_id, " + AMOUNT_SUM + " AS amount, " + DUE + " AS due,"
78	                        + " " + DERIVED_STATUS + " AS status, i.issued_date, i.due_date, i.discount_pct, i.tax_pct"
79	                        + " FROM invoices i WHERE i.project_id = ?"
80	                        + " ORDER BY i.due_date ASC NULLS LAST, i.id",
81	                MAPPER, projectId);
82	    }
83	
84	    private static final org.springframework.jdbc.core.RowMapper<InvoiceListing> LISTING_MAPPER =
85	            (rs, i) -> new InvoiceListing(rs.getLong("id"), rs.getLong("project_id"),
86	                    rs.getString("project_name"), rs.getBigDecimal("amount"),
87	                    rs.getString("status"));
88	
89	    // Every invoice joined to its project name, ordered by id. The derived status is an expression,
90	    // so filtering by stage wraps this as a subquery and filters on the aliased column.
91	    private static final String LISTING_SELECT =
92	            "SELECT i.id AS id, i.project_id AS project_id, p.name AS project_name, "
93	                    + AMOUNT_SUM + " AS amount, " + DERIVED_STATUS + " AS status FROM invoices i"
94	                    + " JOIN projects p ON p.id = i.project_id";
95	
96	    /** Every invoice across all projects, joined to its project name, ordered by id. */
97	    public List<InvoiceListing> findAllWithProject() {
98	        return jdbc.query(LISTING_SELECT + " ORDER BY id", LISTING_MAPPER);
99	    }
100	
101	    /**
102	     * One page of the cross-project invoice list, ordered by id. {@code status} narrows to a single
103	     * stage (DRAFT/SENT/PARTIAL/PAID) when non-null/blank; otherwise every stage is included.
104	     */
105	    public List<InvoiceListing> findPage(String status, int limit, int offset) {
106	        if (status == null || status.isBlank()) {
107	            return jdbc.query(LISTING_SELECT + " ORDER BY id LIMIT ? OFFSET ?",
108	                    LISTING_MAPPER, limit, offset);
109	        }
110	        return jdbc.query(
111	                "SELECT id, project_id, project_name, amount, status FROM (" + LISTING_SELECT
112	                        + ") t WHERE t.status = ? ORDER BY id LIMIT ? OFFSET ?",
113	                LISTING_MAPPER, status, limit, offset);
114	    }
115	
116	    /** How many invoices match the (optional) stage filter, across every page. */
117	    public long countAll(String status) {
118	        if (status == null || status.isBlank()) {
119	            return jdbc.queryForObject("SELECT COUNT(*) FROM invoices", Long.class);
120	        }
121	        return jdbc.queryForObject(
122	                "SELECT COUNT(*) FROM (" + LISTING_SELECT + ") t WHERE t.status = ?",
123	                Long.class, status);
124	    }
125	
126	    public Invoice findById(long id) {
127	        List<Invoice> found = jdbc.query(
128	                "SELECT i.id, i.project_id, " + AMOUNT_SUM + " AS amount, " + DUE + " AS due,"
129	                        + " " + DERIVED_STATUS + " AS status, i.issued_date, i.due_date, i.discount_pct, i.tax_pct"
130	                        + " FROM invoices i WHERE i.id = ?",
131	                MAPPER, id);
132	        return found.isEmpty() ? null : found.get(0);
133	    }
134	
135	    public Invoice create(long projectId, BigDecimal amount) {
136	        KeyHolder keys = new GeneratedKeyHolder();
137	        jdbc.update(con -> {
138	            var ps = con.prepareStatement(
139	                    "INSERT INTO invoices (project_id, amount) VALUES (?, ?)", new String[] {"id"});
140	            ps.setLong(1, projectId);
141	            ps.setBigDecimal(2, amount);
142	            return ps;
143	        }, keys);
144	        // A freshly created invoice has no payments yet, so the whole amount is still due, and no
145	        // discount or tax yet (discount_pct and tax_pct default to 0).
146	        return new Invoice(keys.getKey().longValue(), projectId, amount, "DRAFT", null, null,
147	                amount, BigDecimal.ZERO, BigDecimal.ZERO);
148	    }
149	
150	    /** Flip an invoice from DRAFT to SENT and return the updated row (null if no such invoice). */
151	    public Invoice markSent(long id) {
152	        jdbc.update("UPDATE invoices SET status = 'SENT' WHERE id = ?", id);
153	        return findById(id);
154	    }
155	
156	    /** Flip an invoice to PAID and return the updated row (null if no such invoice). */
157	    public Invoice markPaid(long id) {
158	        jdbc.update("UPDATE invoices SET status = 'PAID' WHERE id = ?", id);
159	        return findById(id);
160	    }
161	
162	    /** Cancel (void) an invoice and return the updated row (null if no such invoice). */
163	    public Invoice markVoid(long id) {
164	        jdbc.update("UPDATE invoices SET status = 'VOID' WHERE id = ?", id);
165	        return findById(id);
166	    }
167	}
168

