16	
17	/**
18	 * Per-spec data setup for the harness (DESIGN.md §9). Profile-guarded so it exists ONLY under the
19	 * harness launch (bin/start sets spring.profiles.active=harness) — never in a real deploy. This is
20	 * APP CODE and EVOLVES with the schema (NOT pinned); a change that breaks a prior spec's seed is a
21	 * seed-path regression. Tests call these to ARRANGE data; they ASSERT only through the UI.
22	 *
23	 * <p>{@code seed} is one helper per table so a new entity is a new {@code seedX} method plus one
24	 * call, not surgery on a growing monolith; {@code reset} is data-driven off {@link #DOMAIN_TABLES}.
25	 */
26	@Profile("harness")
27	@RestController
28	@RequestMapping("/__test__")
29	public class TestSupportController {
30	
31	    /**
32	     * Every domain table, cleared on reset. Order is irrelevant: referential integrity is lifted
33	     * for the truncate and {@code RESTART IDENTITY} resets each table's generator. Add a table here
34	     * when its schema arrives.
35	     */
36	    private static final List<String> DOMAIN_TABLES = List.of(
37	            "notes", "project_tags", "tags", "tasks", "payments", "line_items",
38	            "invoices", "contacts", "projects", "clients", "dashboard_settings");
39	
40	    private final Audit audit;
41	    private final JdbcTemplate jdbc;
42	
43	    public TestSupportController(Audit audit, JdbcTemplate jdbc) {
44	        this.audit = audit;
45	        this.jdbc = jdbc;
46	    }
47	
48	    /** Truncate all domain tables and clear the audit file so each spec starts clean. */
49	    @PostMapping("/reset")
50	    public void reset() {
51	        audit.clear();
52	        // projects references clients (FK); H2 refuses to TRUNCATE an FK-referenced table, so lift
53	        // referential integrity for the duration of the reset.
54	        jdbc.execute("SET REFERENTIAL_INTEGRITY FALSE");
55	        try {
56	            for (String table : DOMAIN_TABLES) {
57	                jdbc.execute("TRUNCATE TABLE " + table + " RESTART IDENTITY");
58	            }
59	        } finally {
60	            jdbc.execute("SET REFERENTIAL_INTEGRITY TRUE");
61	        }
62	    }
63	
64	    /** Insert the fixture a spec needs; each table has its own {@code seedX} helper below. */
65	    @PostMapping("/seed")
66	    public void seed(@RequestBody Map<String, Object> fixture) {
67	        seedClients(fixture);
68	        seedProjects(fixture);
