1	// Data access + validation for the clients feature, kept in one place so the page and its forms
2	// share a single definition of "what a client is" and "how we talk to the server" (CLAUDE.md —
3	// keep each feature's code together; features own their state).
4	export type Client = { id: number; name: string; email: string };
5	
6	// Every client needs a proper email address. Kept in sync with the server-side check in
7	// ClientsPostLogic and the DB CHECK constraint (V2__clients_email_check.sql).
8	const EMAIL_PATTERN = /^[^@\s]+@[^@\s]+\.[^@\s]+$/;
9	
10	export const INVALID_EMAIL = 'Enter a valid email address.';
11	export const DUPLICATE_EMAIL = 'A client with this email already exists.';
12	
13	// Validate an email before it reaches the server. `takenEmails` are the emails this one must not
14	// collide with (the server and the clients_email_unique constraint are the authoritative guards).
15	// Returns the error to show, or '' when the email is acceptable.
16	export function validateEmail(email: string, takenEmails: string[]): string {
17	  const trimmed = email.trim();
18	  if (!EMAIL_PATTERN.test(trimmed)) {
19	    return INVALID_EMAIL;
20	  }
21	  if (takenEmails.includes(trimmed)) {
22	    return DUPLICATE_EMAIL;
23	  }
24	  return '';
25	}
26	
27	// How much a single client still owes across all of their invoices, keyed by client id.
28	export type ClientOutstanding = { clientId: number; outstanding: number };
29	
30	// Load the full client list. Returns null when the request fails so callers can keep what they
31	// already have rather than blanking the list.
32	export async function fetchClients(): Promise<Client[] | null> {
33	  const res = await fetch('/api/clients');
34	  return res.ok ? res.json() : null;
35	}
36	
37	// Load how much each client owes, so the list can be sorted by amount owed. Returns null on failure
38	// so the caller can fall back to a name sort rather than blanking the list.
39	export async function fetchOutstanding(): Promise<ClientOutstanding[] | null> {
40	  const res = await fetch('/api/clients/outstanding');
41	  return res.ok ? res.json() : null;
42	}
